// ─── USER MANAGEMENT ────────────────────────────────────────────────────────
function UserManagement({ users, setUsers, currentUser }) {
  const [showForm, setShowForm] = useState(false);
  const [editUser, setEditUser] = useState(null);
  const [form, setForm]         = useState({ username:"", password:"", name:"", role:"evaluator", team:"Team 1", title:"", active:true });
  const [err, setErr]           = useState("");
  const [search, setSearch]     = useState("");
  const [filterTeam, setFilterTeam] = useState("");

  const openNew  = ()=>{ setForm({username:"",password:"",name:"",role:"evaluator",team:"Team 1",title:"",active:true}); setEditUser(null); setErr(""); setShowForm(true); };
  const openEdit = u=>{ setForm({...u}); setEditUser(u); setErr(""); setShowForm(true); };

  const save = () => {
    if(!form.username||!form.name){ setErr("Username na amazina yose ni ngombwa / Username and full name are required."); return; }
    if(!editUser&&!form.password){ setErr("Ijambo ry'ibanga ni ngombwa / Password required for new users."); return; }
    if(!editUser&&users.find(u=>u.username===form.username)){ setErr("Iri zina riramaze gukoreshwa / Username already taken."); return; }
    const saved = editUser ? {...editUser,...form,...(form.password?{}:{password:editUser.password})} : {...form,id:Date.now().toString(),createdAt:new Date().toISOString().split("T")[0]};
    setUsers(p=>editUser?p.map(u=>u.id===editUser.id?saved:u):[...p,saved]);
    setShowForm(false);
  };

  const teams = ["Overall Lead","Team 1","Team 2","Team 3","Team 4","Team 5"];
  const filtered = users.filter(u=>
    (!filterTeam||u.team===filterTeam)&&
    (!search||u.name.toLowerCase().includes(search.toLowerCase())||u.username.includes(search))
  );

  // Group by team
  const grouped = {};
  filtered.forEach(u=>{ if(!grouped[u.team]) grouped[u.team]=[]; grouped[u.team].push(u); });

  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontSize:18,fontWeight:800,color:"#1E293B"}}>👥 Gucunga Abakoresha · User Management</div>
          <div style={{fontSize:12,color:"#94A3B8"}}>Itsinda ry'Abagenzuzi 5 · 5 Quality Assurance Teams · {users.length} users</div>
        </div>
        <button onClick={openNew} style={{padding:"9px 18px",borderRadius:8,border:"none",background:"#1E293B",color:"white",cursor:"pointer",fontSize:13,fontWeight:600,display:"flex",alignItems:"center",gap:6}}>
          ➕ Ongeraho / Add User
        </button>
      </div>

      <div style={{display:"flex",gap:8,marginBottom:14,flexWrap:"wrap"}}>
        <div style={{position:"relative",flex:1,minWidth:180}}>
          <span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",color:"#94A3B8",fontSize:13}}>🔍</span>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Shakisha umukoresha..."
            style={{width:"100%",padding:"8px 10px 8px 32px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box"}}/>
        </div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          <button onClick={()=>setFilterTeam("")} style={{padding:"7px 12px",borderRadius:20,border:`2px solid ${!filterTeam?"#334155":"#E2E8F0"}`,background:!filterTeam?"#334155":"white",color:!filterTeam?"white":"#64748B",cursor:"pointer",fontSize:11,fontWeight:600}}>All</button>
          {teams.map(t=><button key={t} onClick={()=>setFilterTeam(t===filterTeam?"":t)} style={{padding:"7px 12px",borderRadius:20,border:`2px solid ${filterTeam===t?TEAM_COLORS[t]:"#E2E8F0"}`,background:filterTeam===t?TEAM_COLORS[t]:"white",color:filterTeam===t?"white":"#64748B",cursor:"pointer",fontSize:11,fontWeight:600}}>{t}</button>)}
        </div>
      </div>

      {Object.entries(grouped).map(([team, members])=>(
        <div key={team} style={{marginBottom:20}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10,padding:"8px 14px",background:TEAM_COLORS[team]||"#334155",borderRadius:10}}>
            <span style={{color:"white",fontSize:14,fontWeight:800}}>{team}</span>
            <span style={{color:"rgba(255,255,255,.6)",fontSize:12}}>· {members.length} members</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:6,paddingLeft:8}}>
            {members.map(u=>{
              const rm = ROLE_META[u.role]||ROLE_META.evaluator;
              return (
                <div key={u.id} style={{background:"white",borderRadius:10,padding:"12px 16px",border:"1px solid #F1F5F9",display:"flex",alignItems:"center",gap:12,opacity:u.active?1:.6}}>
                  <div style={{width:40,height:40,borderRadius:10,background:rm.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0}}>{rm.icon}</div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontSize:13,fontWeight:700,color:"#1E293B"}}>{u.name}</div>
                    <div style={{fontSize:11,color:"#64748B"}}>@{u.username} · {u.title}</div>
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                    <span style={{background:rm.light,color:rm.bg,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>{rm.label}</span>
                    <span style={{background:u.active?"#D1FAE5":"#F1F5F9",color:u.active?"#065F46":"#94A3B8",borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:600}}>{u.active?"Active":"Inactive"}</span>
                    {u.id!==currentUser.id&&<>
                      <button onClick={()=>openEdit(u)} style={{padding:"4px 8px",borderRadius:6,border:"1px solid #E2E8F0",background:"white",cursor:"pointer",fontSize:11,color:"#334155"}}>✏️</button>
                      <button onClick={()=>setUsers(p=>p.map(x=>x.id===u.id?{...x,active:!x.active}:x))} style={{padding:"4px 8px",borderRadius:6,border:"1px solid #E2E8F0",background:"white",cursor:"pointer",fontSize:11,color:u.active?"#D97706":"#10B981"}}>{u.active?"⏸":"▶"}</button>
                      <button onClick={()=>{if(window.confirm("Delete?"))setUsers(p=>p.filter(x=>x.id!==u.id));}} style={{padding:"4px 8px",borderRadius:6,border:"1px solid #FCA5A5",background:"#FEF2F2",cursor:"pointer",fontSize:11,color:"#DC2626"}}>🗑️</button>
                    </>}
                    {u.id===currentUser.id&&<span style={{fontSize:11,color:"#94A3B8"}}>(you)</span>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {/* Modal */}
      {showForm&&(
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,padding:20}}>
          <div style={{background:"white",borderRadius:16,padding:28,width:"100%",maxWidth:460,boxShadow:"0 24px 60px rgba(0,0,0,.3)",maxHeight:"90vh",overflowY:"auto"}}>
            <div style={{fontSize:17,fontWeight:800,color:"#1E293B",marginBottom:18}}>{editUser?"Hindura Umukoresha · Edit User":"Umukoresha Mushya · New User"}</div>
            {err&&<div style={{background:"#FEE2E2",borderRadius:8,padding:"8px 12px",fontSize:12,color:"#DC2626",marginBottom:14}}>⚠️ {err}</div>}
            {[{l:"Amazina yose · Full Name *",k:"name",ph:"e.g. NSHIMIYIMANA Emmanuel",t:"text"},
              {l:"Izina ryo kwinjira · Username *",k:"username",ph:"e.g. nshimiyimana",t:"text",dis:!!editUser},
              {l:"Ijambo ry'ibanga · Password"+(editUser?" (leave blank = keep)":"")+" *",k:"password",ph:"Min 6 characters",t:"password"},
              {l:"Umwanya · Title",k:"title",ph:"e.g. Team Leader",t:"text"},
            ].map(f=>(
              <div key={f.k} style={{marginBottom:12}}>
                <label style={{fontSize:11,fontWeight:600,color:"#64748B",display:"block",marginBottom:4}}>{f.l}</label>
                <input value={form[f.k]||""} onChange={e=>setForm(p=>({...p,[f.k]:e.target.value}))} placeholder={f.ph} type={f.t||"text"} disabled={f.dis}
                  style={{width:"100%",padding:"10px 12px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box",opacity:f.dis?.5:1,fontFamily:"inherit"}}/>
              </div>
            ))}
            <div style={{marginBottom:12}}>
              <label style={{fontSize:11,fontWeight:600,color:"#64748B",display:"block",marginBottom:6}}>Itsinda · Team *</label>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {["Overall Lead","Team 1","Team 2","Team 3","Team 4","Team 5"].map(t=>(
                  <button key={t} onClick={()=>setForm(p=>({...p,team:t}))}
                    style={{padding:"6px 12px",borderRadius:20,border:`2px solid ${form.team===t?TEAM_COLORS[t]||"#334155":"#E2E8F0"}`,background:form.team===t?TEAM_COLORS[t]||"#334155":"white",color:form.team===t?"white":"#64748B",cursor:"pointer",fontSize:12,fontWeight:600}}>
                    {t}
                  </button>
                ))}
              </div>
            </div>
            <div style={{marginBottom:12}}>
              <label style={{fontSize:11,fontWeight:600,color:"#64748B",display:"block",marginBottom:6}}>Uruhare · Role *</label>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {Object.entries(ROLE_META).map(([r,rm])=>(
                  <button key={r} onClick={()=>setForm(p=>({...p,role:r}))}
                    style={{flex:1,padding:"8px 6px",borderRadius:8,border:`2px solid ${form.role===r?rm.bg:"#E2E8F0"}`,background:form.role===r?rm.bg:"white",color:form.role===r?"white":"#64748B",cursor:"pointer",fontSize:11,fontWeight:600,display:"flex",alignItems:"center",justifyContent:"center",gap:4}}>
                    {rm.icon} {rm.label}
                  </button>
                ))}
              </div>
            </div>
            <div style={{marginBottom:20,display:"flex",alignItems:"center",gap:8}}>
              <input type="checkbox" id="activeChk" checked={form.active} onChange={e=>setForm(p=>({...p,active:e.target.checked}))} style={{width:16,height:16}}/>
              <label htmlFor="activeChk" style={{fontSize:13,color:"#334155",cursor:"pointer"}}>Konti ikora · Account Active</label>
            </div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setShowForm(false)} style={{flex:1,padding:11,borderRadius:8,border:"1.5px solid #E2E8F0",background:"white",color:"#64748B",cursor:"pointer",fontSize:13,fontWeight:600}}>Reka / Cancel</button>
              <button onClick={save} style={{flex:2,padding:11,borderRadius:8,border:"none",background:"#1E293B",color:"white",cursor:"pointer",fontSize:13,fontWeight:700}}>💾 Bika / Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── SETUP VIEW ─────────────────────────────────────────────────────────────
function SetupView({ selectedPillar, setSelectedPillar, onSelect, evaluatorName, setEvaluatorName, evaluationDate, setEvaluationDate, searchTerm, setSearchTerm, readOnly, currentUser }) {
  const filtered = IMIHIGO_DATA.filter(u=>
    (!selectedPillar||u.pillar===selectedPillar)&&
    (!searchTerm||u.title.toLowerCase().includes(searchTerm.toLowerCase())||String(u.number).includes(searchTerm)||(u.responsible||"").toLowerCase().includes(searchTerm.toLowerCase()))
  );
  return (
    <div>
      {!readOnly&&(
        <div style={{background:"white",borderRadius:14,padding:18,boxShadow:"0 2px 10px rgba(0,0,0,.06)",marginBottom:18,border:"1px solid #F1F5F9"}}>
          <div style={{fontSize:13,fontWeight:700,color:"#334155",marginBottom:12,display:"flex",alignItems:"center",gap:6}}>👤 Evaluator Information</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
            <div>
              <label style={{fontSize:11,color:"#64748B",display:"block",marginBottom:4,fontWeight:500}}>Amazina y'uwakoze isuzuma *</label>
              <input value={evaluatorName} onChange={e=>setEvaluatorName(e.target.value)} placeholder="Full name..."
                style={{width:"100%",padding:"9px 12px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box"}}/>
            </div>
            <div>
              <label style={{fontSize:11,color:"#64748B",display:"block",marginBottom:4,fontWeight:500}}>Itariki y'isuzuma *</label>
              <input type="date" value={evaluationDate} onChange={e=>setEvaluationDate(e.target.value)}
                style={{width:"100%",padding:"9px 12px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box"}}/>
            </div>
          </div>
        </div>
      )}
      <div style={{marginBottom:16}}>
        <div style={{fontSize:12,fontWeight:700,color:"#64748B",marginBottom:8,textTransform:"uppercase",letterSpacing:".5px"}}>Hitamo Umurongo / Select Cluster · Pillar</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <button onClick={()=>setSelectedPillar("")} style={{padding:"7px 16px",borderRadius:20,border:`2px solid ${!selectedPillar?"#334155":"#E2E8F0"}`,background:!selectedPillar?"#334155":"white",color:!selectedPillar?"white":"#64748B",cursor:"pointer",fontSize:12,fontWeight:600}}>Byose ({IMIHIGO_DATA.length})</button>
          {PILLARS.map(p=>{ const c=PILLAR_COLORS[p]; const active=selectedPillar===p; const cnt=IMIHIGO_DATA.filter(u=>u.pillar===p).length;
            return <button key={p} onClick={()=>setSelectedPillar(p)} style={{padding:"7px 16px",borderRadius:20,border:`2px solid ${active?c.accent:c.border}`,background:active?c.bg:"white",color:active?"white":c.bg,cursor:"pointer",fontSize:12,fontWeight:600}}>{PILLAR_SHORT[p]} ({cnt})</button>; })}
        </div>
      </div>
      <div style={{position:"relative",marginBottom:12}}>
        <span style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",color:"#94A3B8"}}>🔍</span>
        <input value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} placeholder="Shakisha Umuhigo / Search by title, number or responsible..."
          style={{width:"100%",padding:"10px 12px 10px 36px",border:"1.5px solid #E2E8F0",borderRadius:10,fontSize:13,outline:"none",boxSizing:"border-box",background:"white"}}/>
      </div>
      <div style={{fontSize:12,color:"#94A3B8",marginBottom:8}}>{filtered.length} Imihigo · {readOnly?"Kanda kureba / Click to view":"Kanda gutangira isuzuma / Click to evaluate"}</div>
      <div style={{display:"flex",flexDirection:"column",gap:6}}>
        {filtered.map(u=>{
          const c=PILLAR_COLORS[u.pillar];
          return (
            <div key={u.number} onClick={()=>onSelect(u)}
              style={{background:"white",borderRadius:10,padding:"12px 16px",border:"1px solid #F1F5F9",cursor:"pointer",display:"flex",alignItems:"flex-start",gap:12,transition:"all .2s",boxShadow:"0 1px 4px rgba(0,0,0,.04)"}}
              onMouseEnter={e=>{e.currentTarget.style.boxShadow="0 4px 16px rgba(0,0,0,.1)";e.currentTarget.style.borderColor=c.border;}}
              onMouseLeave={e=>{e.currentTarget.style.boxShadow="0 1px 4px rgba(0,0,0,.04)";e.currentTarget.style.borderColor="#F1F5F9";}}>
              <div style={{background:c.bg,color:"white",borderRadius:8,minWidth:42,height:34,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:800,flexShrink:0}}>#{u.number}</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontSize:13,fontWeight:600,color:"#1E293B",lineHeight:1.4}}>{u.title}</div>
                {u.subtitle&&<div style={{fontSize:11,color:"#94A3B8",marginTop:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{u.subtitle}</div>}
                <div style={{fontSize:11,color:"#64748B",marginTop:4,display:"flex",gap:8,flexWrap:"wrap"}}>
                  <span>👤 {u.responsible}</span>
                  <span style={{background:c.light,color:c.bg,padding:"1px 6px",borderRadius:4,fontWeight:600}}>{u.items.length} items</span>
                </div>
              </div>
              <div style={{fontSize:11,color:c.accent,fontWeight:700,whiteSpace:"nowrap",alignSelf:"center"}}>{readOnly?"Reba →":"Suzuma →"}</div>
            </div>
          );
        })}
        {filtered.length===0&&<div style={{textAlign:"center",padding:40,color:"#94A3B8"}}>Nta Muhigo uboneka / No Imihigo found.</div>}
      </div>
    </div>
  );
}

// ─── EVALUATION VIEW ─────────────────────────────────────────────────────────
function EvaluationView({ umuhigo, answers, setAnswers, notes, setNotes, uploads, setUploads, implStatus, setImplStatus, onSave, onBack, readOnly }) {
  const c=PILLAR_COLORS[umuhigo.pillar]; const items=umuhigo.items;
  const answered=items.filter(i=>answers[i.num]).length;
  const yego=items.filter(i=>answers[i.num]==="yego").length;
  const oya=items.filter(i=>answers[i.num]==="oya").length;
  const naC=items.filter(i=>answers[i.num]==="na"||answers[i.num]==="not_yet").length;
  const denom=items.filter(i=>answers[i.num]&&answers[i.num]!=="na").length;
  const pct=denom>0?Math.round((yego/denom)*100):0;
  const handleUpload=(num,f)=>setUploads(p=>({...p,[num]:[...(p[num]||[]),f]}));
  const handleRemove=(num,id)=>setUploads(p=>({...p,[num]:(p[num]||[]).filter(f=>f.id!==id)}));

  return (
    <div>
      <div style={{background:`linear-gradient(135deg,${c.bg},${c.bg}ee)`,borderRadius:14,padding:"18px 20px",color:"white",marginBottom:18,boxShadow:`0 6px 20px ${c.bg}55`}}>
        <button onClick={onBack} style={{background:"rgba(255,255,255,.15)",border:"none",color:"white",borderRadius:8,padding:"5px 12px",cursor:"pointer",fontSize:12,marginBottom:10}}>← Subira / Back</button>
        <div style={{fontSize:11,opacity:.7,marginBottom:4}}>{umuhigo.pillar} · Umuhigo N°{umuhigo.number}</div>
        <div style={{fontSize:16,fontWeight:700,lineHeight:1.4,marginBottom:4}}>{umuhigo.title}</div>
        {umuhigo.subtitle&&<div style={{fontSize:12,opacity:.8,marginBottom:6}}>{umuhigo.subtitle}</div>}
        <div style={{fontSize:12,opacity:.8}}>👤 {umuhigo.responsible}</div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:14}}>
          <div style={{display:"flex",gap:16}}>
            {[{l:"Yego",v:yego,cl:"#6EE7B7"},{l:"Oya",v:oya,cl:"#FCA5A5"},{l:"N/A",v:naC,cl:"#FDE68A"},{l:"Pending",v:items.length-answered,cl:"rgba(255,255,255,.5)"}].map(s=>(
              <div key={s.l} style={{textAlign:"center"}}>
                <div style={{fontSize:20,fontWeight:800,color:s.cl}}>{s.v}</div>
                <div style={{fontSize:10,opacity:.7}}>{s.l}</div>
              </div>
            ))}
          </div>
          <div style={{textAlign:"right"}}>
            <div style={{fontSize:36,fontWeight:800}}>{pct}%</div>
            <div style={{fontSize:11,opacity:.7}}>{answered}/{items.length} answered</div>
          </div>
        </div>
        <div style={{background:"rgba(255,255,255,.2)",borderRadius:4,height:5,marginTop:10}}>
          <div style={{background:"white",borderRadius:4,height:"100%",width:`${items.length?answered/items.length*100:0}%`,transition:"width .3s"}}/>
        </div>
      </div>

      <div style={{background:"white",borderRadius:14,padding:18,boxShadow:"0 2px 10px rgba(0,0,0,.06)",marginBottom:16,border:"1px solid #F1F5F9"}}>
        <div style={{fontSize:14,fontWeight:800,color:"#1E293B",marginBottom:16,paddingBottom:10,borderBottom:"2px solid #F1F5F9",display:"flex",alignItems:"center",gap:8}}>
          <span style={{background:c.bg,color:"white",borderRadius:6,padding:"3px 8px",fontSize:12}}>📄</span>
          INYANDIKO ZA NGOMBWA KU MUHIGO
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          {items.map(item=>{
            const ans=answers[item.num]; const resp=RESPONSES.find(r=>r.value===ans); const hasNote=notes[item.num]!==undefined;
            return (
              <div key={item.num} style={{border:`1.5px solid ${resp?resp.color+"55":"#E2E8F0"}`,borderRadius:10,padding:14,background:resp?resp.bg+"33":"#FAFAFA",transition:"all .2s"}}>
                <div style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:10}}>
                  <span style={{background:c.bg,color:"white",borderRadius:6,padding:"3px 9px",fontSize:12,fontWeight:700,flexShrink:0}}>{item.num}</span>
                  <div style={{flex:1}}>
                    <div style={{fontSize:13,color:"#1E293B",lineHeight:1.5,fontWeight:500}}>{item.text}</div>
                    {item.ibyagaragaye&&<div style={{marginTop:4,fontSize:11,color:"#0369A1",background:"#E0F2FE",borderRadius:4,padding:"2px 8px",display:"inline-block"}}>💬 {item.ibyagaragaye}</div>}
                    {item.ibikeneye&&<div style={{marginTop:4,fontSize:11,color:"#7C3AED",background:"#EDE9FE",borderRadius:4,padding:"2px 8px",display:"inline-block",marginLeft:4}}>🔧 {item.ibikeneye}</div>}
                  </div>
                  {resp&&<span style={{fontSize:12,fontWeight:700,color:resp.color,background:resp.bg,borderRadius:6,padding:"3px 8px",whiteSpace:"nowrap"}}>{resp.label}</span>}
                </div>
                {!readOnly&&(
                  <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>
                    {RESPONSES.map(r=>(
                      <button key={r.value} onClick={()=>setAnswers(p=>({...p,[item.num]:r.value}))}
                        style={{padding:"6px 14px",borderRadius:20,border:`2px solid ${ans===r.value?r.color:"#E2E8F0"}`,background:ans===r.value?r.color:"white",color:ans===r.value?"white":"#64748B",cursor:"pointer",fontSize:12,fontWeight:ans===r.value?700:400}}>
                        {r.label}
                      </button>
                    ))}
                  </div>
                )}
                <FileUploadZone itemNum={item.num} uploads={uploads} onUpload={handleUpload} onRemove={handleRemove} color={c} readOnly={readOnly}/>
                {!readOnly&&(
                  <div style={{marginTop:8}}>
                    <button onClick={()=>setNotes(p=>({...p,[item.num]:hasNote?undefined:""}))}
                      style={{background:"none",border:"1px solid #E2E8F0",borderRadius:6,padding:"4px 10px",fontSize:11,color:"#64748B",cursor:"pointer"}}>
                      {hasNote?"✏️ Hisha inyandiko / Hide note":"📝 Ongeraho inyandiko / Add note"}
                    </button>
                    {hasNote&&<textarea value={notes[item.num]||""} onChange={e=>setNotes(p=>({...p,[item.num]:e.target.value}))} placeholder="Ibyagaragaye / Ibikeneye kunozwa..."
                      style={{width:"100%",marginTop:6,padding:"8px 10px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",resize:"vertical",minHeight:60,boxSizing:"border-box",fontFamily:"inherit"}}/>}
                  </div>
                )}
                {readOnly&&notes[item.num]&&<div style={{marginTop:8,fontSize:12,color:"#64748B",fontStyle:"italic",background:"#F8FAFC",padding:"6px 10px",borderRadius:6}}>📝 {notes[item.num]}</div>}
              </div>
            );
          })}
        </div>
      </div>

      {!readOnly&&(
        <>
          <div style={{background:"white",borderRadius:14,padding:16,boxShadow:"0 2px 10px rgba(0,0,0,.06)",marginBottom:18,border:"1px solid #F1F5F9"}}>
            <div style={{fontSize:13,fontWeight:700,color:"#334155",marginBottom:8}}>📈 Implementation Status (Supported Progress)</div>
            <input value={implStatus} onChange={e=>setImplStatus(e.target.value)} placeholder="e.g. 75%, 100%, In Progress, Q3 target met..."
              style={{width:"100%",padding:"10px 12px",border:"1.5px solid #E2E8F0",borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box"}}/>
          </div>
          <div style={{display:"flex",gap:10,justifyContent:"flex-end"}}>
            <button onClick={onBack} style={{padding:"11px 22px",borderRadius:8,border:"1.5px solid #E2E8F0",background:"white",color:"#64748B",cursor:"pointer",fontSize:13,fontWeight:600}}>← Reka / Cancel</button>
            <button onClick={onSave} style={{padding:"11px 28px",borderRadius:8,border:"none",background:`linear-gradient(135deg,${c.bg},${c.accent})`,color:"white",cursor:"pointer",fontSize:14,fontWeight:700,boxShadow:`0 4px 14px ${c.bg}44`}}>
              💾 Bika Isuzuma / Save Evaluation
            </button>
          </div>
        </>
      )}
    </div>
  );
}

// ─── SUMMARY VIEW ────────────────────────────────────────────────────────────
function SummaryView({ ev, onNew, onHistory }) {
  const c=PILLAR_COLORS[ev.umuhigo.pillar];
  const docs=Object.values(ev.uploads||{}).flat().length;
  return (
    <div>
      <div style={{background:`linear-gradient(135deg,${c.bg},${c.accent})`,borderRadius:16,padding:28,color:"white",marginBottom:22,textAlign:"center",boxShadow:`0 8px 28px ${c.bg}66`}}>
        <div style={{fontSize:48,marginBottom:8}}>✅</div>
        <div style={{fontSize:22,fontWeight:800}}>Isuzuma Ryabitswe! / Evaluation Saved!</div>
        <div style={{fontSize:13,opacity:.8,marginTop:4}}>Umuhigo #{ev.umuhigo.number} · {ev.date} · {ev.evaluator}</div>
        <div style={{fontSize:11,opacity:.6,marginTop:2}}>Itsinda: {ev.team} · {ev.teamRole}</div>
        <div style={{fontSize:48,fontWeight:900,marginTop:16}}>{ev.score.pct}%</div>
        <div style={{fontSize:12,opacity:.7}}>Compliance Score</div>
        <div style={{display:"flex",gap:24,justifyContent:"center",marginTop:16}}>
          {[{l:"Yego",v:ev.score.yes,cl:"#A7F3D0"},{l:"Oya",v:ev.score.no,cl:"#FCA5A5"},{l:"N/A",v:ev.score.na,cl:"#FDE68A"},{l:"Docs",v:docs,cl:"#BAE6FD"}].map(s=>(
            <div key={s.l} style={{textAlign:"center"}}><div style={{fontSize:24,fontWeight:800,color:s.cl}}>{s.v}</div><div style={{fontSize:11,opacity:.7}}>{s.l}</div></div>
          ))}
        </div>
      </div>
      <div style={{display:"flex",gap:10,justifyContent:"center",flexWrap:"wrap"}}>
        <button onClick={onNew} style={{padding:"11px 24px",borderRadius:8,border:"none",background:`linear-gradient(135deg,${c.bg},${c.accent})`,color:"white",cursor:"pointer",fontSize:13,fontWeight:700}}>+ Isuzuma Rishya / New Evaluation</button>
        <button onClick={onHistory} style={{padding:"11px 20px",borderRadius:8,border:"1.5px solid #E2E8F0",background:"white",color:"#334155",cursor:"pointer",fontSize:13,fontWeight:600}}>📊 Amateka / History</button>
      </div>
    </div>
  );
}

// ─── HISTORY VIEW ────────────────────────────────────────────────────────────
function HistoryView({ evaluations, onNew, isViewer }) {
  if(!evaluations.length) return (
    <div style={{textAlign:"center",padding:"60px 20px",color:"#94A3B8"}}>
      <div style={{fontSize:48,marginBottom:16}}>📊</div>
      <div style={{fontSize:18,fontWeight:600,color:"#334155"}}>Nta mateka arahari / No evaluations yet</div>
      {!isViewer&&<button onClick={onNew} style={{marginTop:20,padding:"10px 24px",borderRadius:8,border:"none",background:"#1E293B",color:"white",cursor:"pointer",fontSize:13,fontWeight:600}}>+ Tangira Isuzuma / Start First Evaluation</button>}
    </div>
  );
  const avg=Math.round(evaluations.reduce((s,e)=>s+e.score.pct,0)/evaluations.length);
  const totalDocs=evaluations.reduce((s,e)=>s+Object.values(e.uploads||{}).flat().length,0);
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10,marginBottom:20}}>
        {[{l:"Evaluations",v:evaluations.length,ico:"📋",col:"#3B82F6"},{l:"Avg Compliance",v:avg+"%",ico:"📈",col:"#10B981"},{l:"Imihigo Covered",v:new Set(evaluations.map(e=>e.umuhigo.number)).size,ico:"🎯",col:"#8B5CF6"},{l:"Docs Uploaded",v:totalDocs,ico:"📎",col:"#F59E0B"}].map(s=>(
          <div key={s.l} style={{background:"white",borderRadius:12,padding:14,textAlign:"center",boxShadow:"0 2px 8px rgba(0,0,0,.05)",border:"1px solid #F1F5F9"}}>
            <div style={{fontSize:22}}>{s.ico}</div>
            <div style={{fontSize:20,fontWeight:800,color:s.col}}>{s.v}</div>
            <div style={{fontSize:11,color:"#94A3B8"}}>{s.l}</div>
          </div>
        ))}
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {evaluations.map(ev=>{
          const c=PILLAR_COLORS[ev.umuhigo.pillar]; const docs=Object.values(ev.uploads||{}).flat().length;
          const tc=TEAM_COLORS[ev.team]||"#334155";
          return (
            <div key={ev.id} style={{background:"white",borderRadius:12,padding:16,border:"1px solid #F1F5F9",boxShadow:"0 1px 6px rgba(0,0,0,.04)"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:4,flexWrap:"wrap"}}>
                    <span style={{background:c.bg,color:"white",borderRadius:5,padding:"2px 8px",fontSize:12,fontWeight:700}}>#{ev.umuhigo.number}</span>
                    <span style={{fontSize:10,background:c.light,color:c.bg,borderRadius:4,padding:"2px 6px",fontWeight:600}}>{PILLAR_SHORT[ev.umuhigo.pillar].replace(/🌾|👥|🏛️/,"").trim()}</span>
                    <span style={{fontSize:10,background:tc,color:"white",borderRadius:4,padding:"2px 6px",fontWeight:600}}>{ev.team}</span>
                  </div>
                  <div style={{fontSize:13,fontWeight:600,color:"#1E293B",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{ev.umuhigo.title}</div>
                  <div style={{fontSize:11,color:"#94A3B8",marginTop:3}}>👤 {ev.evaluator} · 📅 {ev.date} {docs?`· 📎 ${docs} docs`:""}</div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{fontSize:22,fontWeight:800,color:ev.score.pct>=70?"#10B981":ev.score.pct>=40?"#F59E0B":"#EF4444"}}>{ev.score.pct}%</div>
                  <div style={{fontSize:11,color:"#94A3B8"}}>✓{ev.score.yes} ✗{ev.score.no} N/A{ev.score.na}</div>
                </div>
              </div>
              {ev.implStatus&&<div style={{marginTop:8,fontSize:12,color:"#475569",background:"#F8FAFC",borderRadius:6,padding:"4px 8px",display:"inline-block"}}>📈 {ev.implStatus}</div>}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── MAIN APP ────────────────────────────────────────────────────────────────
export default function App() {
  const [users, setUsers]               = useState(DEFAULT_USERS);
  const [currentUser, setCurrentUser]   = useState(null);
  const [view, setView]                 = useState("evaluate");
  const [step, setStep]                 = useState("setup");
  const [selectedPillar, setSelectedPillar] = useState("");
  const [searchTerm, setSearchTerm]     = useState("");
  const [selectedUmuhigo, setSelectedUmuhigo] = useState(null);
  const [evaluatorName, setEvaluatorName]     = useState("");
  const [evaluationDate, setEvaluationDate]   = useState(new Date().toISOString().split("T")[0]);
  const [answers, setAnswers]   = useState({});
  const [notes, setNotes]       = useState({});
  const [uploads, setUploads]   = useState({});
  const [implStatus, setImplStatus] = useState("");
  const [history, setHistory]   = useState([]);

  const handleLogin = (user) => { setCurrentUser(user); setEvaluatorName(user.name); };

  if(!currentUser) return <LoginScreen users={users} onLogin={handleLogin}/>;

  const isViewer    = currentUser.role === "viewer";
  const isAdmin     = currentUser.role === "admin";
  const rm          = ROLE_META[currentUser.role]||ROLE_META.evaluator;
  const tc          = TEAM_COLORS[currentUser.team]||"#334155";

  const startEval = (u) => { setSelectedUmuhigo(u); setAnswers({}); setNotes({}); setUploads({}); setImplStatus(""); setStep("evaluate"); };

  const saveEval = () => {
    const items=selectedUmuhigo.items;
    const yes=items.filter(i=>answers[i.num]==="yego").length;
    const no=items.filter(i=>answers[i.num]==="oya").length;
    const na=items.filter(i=>answers[i.num]==="na"||answers[i.num]==="not_yet").length;
    const denom=items.filter(i=>answers[i.num]&&answers[i.num]!=="na").length;
    setHistory(p=>[{id:Date.now(),umuhigo:selectedUmuhigo,answers:{...answers},notes:{...notes},uploads:{...uploads},implStatus,evaluator:evaluatorName,date:evaluationDate,team:currentUser.team,teamRole:currentUser.title,score:{yes,no,na,total:items.length,pct:denom>0?Math.round((yes/denom)*100):0}},...p]);
    setStep("summary");
  };

  const navTabs = [
    {k:"evaluate",l:"📋 Suzuma / Evaluate",show:true},
    {k:"history",l:`📊 Amateka (${history.length})`,show:true},
    {k:"users",l:"👥 Abakoresha / Users",show:isAdmin},
  ].filter(t=>t.show);

  return (
    <div style={{fontFamily:"'Segoe UI',system-ui,sans-serif",minHeight:"100vh",background:"#F0F4F8"}}>
      {/* NAV */}
      <div style={{background:"linear-gradient(135deg,#0F172A,#1E293B,#0F2027)",padding:"0 20px",boxShadow:"0 4px 20px rgba(0,0,0,.3)",position:"sticky",top:0,zIndex:100}}>
        <div style={{maxWidth:960,margin:"0 auto",display:"flex",alignItems:"center",justifyContent:"space-between",minHeight:60,gap:8,flexWrap:"wrap"}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <div style={{background:"#22C55E",borderRadius:8,width:32,height:32,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16}}>🇷🇼</div>
            <div>
              <div style={{color:"white",fontWeight:800,fontSize:15,lineHeight:1}}>IMIHIGO GAUGE 2025/2026</div>
              <div style={{color:"rgba(255,255,255,.4)",fontSize:10}}>Rwamagana District · Quality Assurance</div>
            </div>
          </div>
          <div style={{display:"flex",gap:2}}>
            {navTabs.map(t=>(
              <button key={t.k} onClick={()=>{setView(t.k);if(t.k==="evaluate")setStep("setup");}}
                style={{padding:"8px 14px",background:view===t.k?"rgba(255,255,255,.15)":"transparent",border:"none",color:"white",cursor:"pointer",fontSize:12,fontWeight:view===t.k?700:400,borderBottom:view===t.k?"2px solid #22C55E":"2px solid transparent",whiteSpace:"nowrap"}}>
                {t.l}
              </button>
            ))}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <div style={{background:"rgba(255,255,255,.08)",borderRadius:8,padding:"5px 10px",display:"flex",alignItems:"center",gap:8}}>
              <div style={{width:28,height:28,background:tc,borderRadius:6,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13}}>{rm.icon}</div>
              <div>
                <div style={{color:"white",fontSize:11,fontWeight:700,lineHeight:1}}>{currentUser.name.split(" ")[0]}</div>
                <div style={{fontSize:9,color:"rgba(255,255,255,.4)",marginTop:1}}>{currentUser.team} · {currentUser.title}</div>
              </div>
            </div>
            <button onClick={()=>{setCurrentUser(null);setView("evaluate");setStep("setup");setHistory([]);}}
              style={{background:"rgba(255,255,255,.08)",border:"none",color:"rgba(255,255,255,.6)",cursor:"pointer",borderRadius:6,padding:"6px 8px",fontSize:11}}>
              🚪
            </button>
          </div>
        </div>
      </div>

      {isViewer&&(
        <div style={{background:"#FEF3C7",borderBottom:"1px solid #FDE68A",padding:"7px 20px",textAlign:"center",fontSize:12,color:"#92400E"}}>
          👁️ <strong>Viewer mode</strong> — Ushobora gusa kureba · Read-only access only
        </div>
      )}

      <div style={{maxWidth:960,margin:"0 auto",padding:"20px 16px"}}>
        {view==="users"&&isAdmin ? (
          <UserManagement users={users} setUsers={setUsers} currentUser={currentUser}/>
        ) : view==="history" ? (
          <HistoryView evaluations={history} onNew={()=>{setView("evaluate");setStep("setup");}} isViewer={isViewer}/>
        ) : step==="setup" ? (
          <SetupView selectedPillar={selectedPillar} setSelectedPillar={setSelectedPillar}
            onSelect={startEval} evaluatorName={evaluatorName} setEvaluatorName={setEvaluatorName}
            evaluationDate={evaluationDate} setEvaluationDate={setEvaluationDate}
            searchTerm={searchTerm} setSearchTerm={setSearchTerm} readOnly={isViewer} currentUser={currentUser}/>
        ) : step==="evaluate" ? (
          <EvaluationView umuhigo={selectedUmuhigo} answers={answers} setAnswers={setAnswers}
            notes={notes} setNotes={setNotes} uploads={uploads} setUploads={setUploads}
            implStatus={implStatus} setImplStatus={setImplStatus}
            onSave={saveEval} onBack={()=>setStep("setup")} readOnly={isViewer}/>
        ) : (
          <SummaryView ev={history[0]} onNew={()=>setStep("setup")} onHistory={()=>setView("history")}/>
        )}
      </div>
    </div>
  );
}
